/* Offline design model only. No application services or real member data. */
(() => {
  'use strict';
  const $ = s => document.querySelector(s);
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon = n => `<i data-lucide="${n}" aria-hidden="true"></i>`;
  const button = (text, action, style = 'primary', attrs = '') => `<button class="${style}" data-action="${action}" ${attrs}>${text}</button>`;
  const ib = (name, action, label, extra = '') => `<button class="icon-btn ${extra}" data-action="${action}" aria-label="${label}" title="${label}">${icon(name)}</button>`;
  const go = (text, route, style = 'text-button') => button(text, `go:${route}`, style);
  const avatar = (name, cls = '') => `<span class="avatar ${cls}" aria-hidden="true">${name.split(' ').map(x => x[0]).slice(0,2).join('')}</span>`;
  const photo = (cls = 'cover') => `<img class="${cls}" src="assets/reunion.png" alt="Illustrative alumni and students gathering on a campus lawn">`;
  const field = (label, name, value = '', type = 'text', extra = '') => `<label class="form-field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
  const textArea = (label, name, value = '', extra = '') => `<label class="form-field">${label}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
  const sectionTitle = (title, action = '') => `<div class="section-title"><h3>${title}</h3>${action}</div>`;
  const tag = (text, cls = '') => `<span class="tag ${cls}">${text}</span>`;
  const row = (name, sub, route, image = avatar(name), end = icon('chevron-right')) => `<button class="row" data-action="go:${route}">${image}<span class="grow"><strong>${name}</strong><span class="small muted">${sub}</span></span>${end}</button>`;
  const screens = [
    ['Join','invitation','Chapter invitation','Belonging before onboarding.','The invitation carries chapter context. Private member details never appear on this entry screen.','Existing invite resolution; visual redesign.'],
    ['Join','signin','Sign in','A short path back.','Clear labels, familiar email sign-in, and a visible recovery path. The prototype does not authenticate.','Existing authentication; no credential collection.'],
    ['Join','signup','Create account','A clear first step.','Only the fields needed for authentication, with the chapter invitation carried forward.','Existing sign-up flow; backend email policy remains authoritative.'],
    ['Join','emailverify','Verify email','Keep the next step clear.','Explain where the verification link goes without claiming delivery or approval.','Existing auth verification and callback flow; prototype sends nothing.'],
    ['Join','reset','Password recovery','Recovery without guessing.','A neutral confirmation protects account existence. The design keeps the chapter invitation context.','Existing recovery flow; callback/native behavior must be verified.'],
    ['Join','essentials','Your essentials','Just enough to join.','Chapter context persists. Graduation year is not an authorization rule; actual membership remains server-controlled.','Existing profile and joining; role designation must remain server-controlled.'],
    ['Join','pending','Awaiting approval','Trust is earned, not illustrated.','An explicit pending state, with a status check and editable details. No member content before approval.','Existing membership state.'],
    ['Everyday','home','Home','The chapter, at a glance.','Prominent gold membership counts, an image-led event, and compact conversations. Active means chapter membership, not online presence.','Existing counts and destinations; event image requires a separate capability.'],
    ['Everyday','notifications','Notifications','Only things worth opening.','Messages, requests and chapter notices grouped into a plain, readable list. No invented urgency or engagement metrics.','Existing notifications; verify each supported type.'],
    ['Events','events','Events agenda','Make the next plan obvious.','Gold date blocks, clear categories, real attendance and large photography on the next event.','Existing agenda/RSVP; covers are a proposed addition.'],
    ['Events','calendar','Events calendar','A calendar, not a dashboard.','One month, a selected day, and the associated agenda. List remains the default for quick scanning.','Calendar presentation is new; use existing event data and timezone semantics.'],
    ['Events','event','Event detail','The invitation is the experience.','A real image and complete logistics, with one persistent RSVP action. The dock has its own layout space.','Covers/calendar export/distribution need capability work; RSVP logic must be preserved.'],
    ['Events','guests','Guest list','People make the plan.','Clear RSVP categories and permission-aware attendee rows. A count never implies all identities can be shown.','Existing preview data; full-list pagination/visibility requires audit.'],
    ['Events','create','Create event','Essentials first.','An inviting cover, title, date, location and description. Optional controls stay behind a disclosure.','Existing form plus proposed cover upload; no migration authorized.'],
    ['Events','review','Review event','Check before publishing.','Preview title, timing, audience and location together. A publish tap must never double-submit.','Proposed review step over existing create service.'],
    ['Events','share','Share event','Private by design.','Share to an existing authorized conversation or copy a protected event link. No guest list in link previews.','New event distribution workflow; recipient authorization and metadata protection required.'],
    ['Chats','chats','Unified inbox','Compact. Familiar. Yours.','Group conversations and accepted mentorship live together, without turning mentorship requests into unsolicited DMs.','Preserve approved Slice 1 inbox contracts; do not invent arbitrary DM support.'],
    ['Chats','conversation','Group conversation','The conversation comes first.','Readable messages, visible timestamps, simple reactions and a clean composer. No unsupported calls or media tray.','Existing group thread and reactions.'],
    ['Chats','threadinfo','Conversation details','Clarity about the room.','Chapter identity and channel description, plus safe access to moderation. Restricted channels remain restricted.','Existing channel metadata; membership listing must respect visibility.'],
    ['Chats','mentorship','Mentorship conversation','Personal, without the pressure.','Accepted mentorship uses the same quiet conversation system. Refresh and timestamps stay accessible.','Existing accepted-request thread only.'],
    ['Chats','requests','Mentorship requests','Introductions with consent.','Read the context before accepting. Declining never opens a conversation or creates a public announcement.','Existing pending/accepted/declined requests.'],
    ['Network','network','Network directory','A network you can use.','Membership, profession and city filters lead to people. The total chapter size is separate from matching results.','Restyle existing People route; label rename is proposed, URL stays stable.'],
    ['Network','filters','Network filters','Find the right person.','Combine membership, industry, city and mentorship availability. Clear filters in one action.','Preserve existing combination and pagination semantics.'],
    ['Network','profile','Member profile','A reason to reach out.','Career context and a member-authored bio lead into a consent-based mentorship request.','Existing profile fields; no enrichment or inferred relationships.'],
    ['Network','request','Request mentorship','Start with a real question.','A short personal note and a useful topic. Sending does not immediately grant messaging access.','Existing request service; duplicate and blocked-user rules retained.'],
    ['Network','opportunities','Opportunities','Useful, not noisy.','A straightforward chapter job list with company, location and a clear destination.','Existing Jobs data/routes.'],
    ['Network','job','Opportunity detail','Context before a click.','Description, poster and an explicit external-application destination. No implied endorsement.','Existing job application validation; no automatic external opening.'],
    ['Network','map','Alumni map','Nearby, not tracked.','A city-level discovery view with an equally usable list. No live location, trail, exact house pin or inferred presence.','Existing Mapbox route/consent; city clustering is a proposed privacy-preserving enhancement.'],
    ['You','me','Me','One place to manage your presence.','Profile, chapter and privacy are easy to find. Admin tools appear only for authorized members.','Existing Me and role gates; admin shown here is a synthetic manager scenario.'],
    ['You','editprofile','Edit profile','Your story, in your words.','Name, professional details and opportunities to help. Map consent is separate from profile editing.','Existing profile fields; avatar uploads retain current safeguards.'],
    ['You','privacy','Map visibility','Off until you choose.','Explain the city, audience and purpose before opting in. Stopping sharing must remove discovery access, not just hide a local pin.','Preserve explicit consent; missing or legacy consent means off.'],
    ['You','settings','Settings & safety','Control without a scavenger hunt.','Account recovery, blocked members and the honest QA deletion limitation. No cosmetic security claims.','Deletion remains unavailable in the QA build; no rebrand may weaken this guard.'],
    ['You','blocked','Blocked members','A boundary you can change.','A clear list and a confirmation before unblocking. Blocked content stays out of search and recommendations.','Existing blocking rules.'],
    ['Chapter tools','admin','Chapter management','Simple stewardship.','Manage pending members, chapter invites and reports without making administration part of every member\'s navigation.','Existing owner/manager authorization must be checked server-side.'],
    ['Chapter tools','approvals','Membership approvals','Review the person, not a badge.','Separate approve and decline decisions, each confirmed. The prototype never changes real membership.','Existing approvals; sample actions are memory-only.'],
    ['Chapter tools','invite','Invite members','Invite with context.','A chapter-bound invitation with expiration and revocation information. Sharing never auto-approves membership.','Existing invite system; verify exposed expiration/revoke contracts.'],
    ['Chapter tools','reports','Reports & moderation','A calm place for hard decisions.','Reports are private to authorized reviewers. Details and decisions are deliberately separate.','Existing moderation routes; no automatic punishments.']
  ];
  const info = Object.fromEntries(screens.map(s => [s[1],s]));
  const s = {screen:'home',state:'ready',rsvp:'going',draftRsvp:'going',chatTab:'All',peopleQuery:'',member:'All',industry:'All',city:'',mentor:false,eventCategory:'All',sharing:false,consent:false,helpFind:true,helpOffer:false,requestSent:false,messages:[],reaction:false,eventDraft:{title:'Back in Santa Barbara',date:'2026-11-07',time:'16:00',location:'Campus lawn, Santa Barbara',description:'An afternoon to reconnect with familiar faces and meet the next generation. Come for a little while or stay for the whole afternoon.',category:'Alumni',end:'18:00'},published:false,optional:false,mapCity:'Santa Barbara',pendingName:'Alex Morgan',approved:false,blocked:true,selectedDay:7};
  const members = [
    {name:'Jordan Lee',year:'2018',kind:'Alumni',job:'Product designer',company:'Northstar',industry:'Technology',city:'San Francisco',mentor:true,cls:''},
    {name:'Maya Patel',year:'2015',kind:'Alumni',job:'Strategy director',company:'Westbridge',industry:'Consulting',city:'Los Angeles',mentor:true,cls:'gold'},
    {name:'Chris Bennett',year:'2021',kind:'Alumni',job:'Financial analyst',company:'Harbor',industry:'Finance',city:'New York',mentor:false,cls:'sage'},
    {name:'Sam Rivera',year:'2027',kind:'Active',job:'Economics student',company:'UCSB',industry:'Finance',city:'Santa Barbara',mentor:false,cls:'rose'},
    {name:'Alex Morgan',year:'2026',kind:'Alumni',job:'Product designer',company:'Northstar',industry:'Technology',city:'San Francisco',mentor:true,cls:''},
    {name:'Taylor Chen',year:'2012',kind:'Alumni',job:'Engineering manager',company:'Fieldwork',industry:'Technology',city:'San Francisco',mentor:true,cls:'gold'}
  ];
  const threads = [
    ['Chapter chat','Sam: See you on the lawn this Saturday.','2m','3','Groups','conversation','gold'],
    ['Alumni weekend','Maya: Looking forward to catching up.','18m','1','Groups','conversation','sage'],
    ['Jordan Lee','Happy to look over your portfolio.','1h','','Mentorship','mentorship',''],
    ['Career conversations','Chris: A role that might be a fit.','Yesterday','','Groups','conversation','rose'],
    ['Class of 2026','Alex: Thanks, everyone!','Tue','','Groups','conversation','']
  ];
  const rootRoutes = ['home','chats','events','network','me'];
  const parent = {notifications:'home',calendar:'events',event:'events',guests:'event',create:'events',review:'create',share:'event',conversation:'chats',threadinfo:'conversation',mentorship:'chats',requests:'chats',filters:'network',profile:'network',request:'profile',opportunities:'network',job:'opportunities',map:'network',editprofile:'me',privacy:'me',settings:'me',blocked:'settings',admin:'me',approvals:'admin',invite:'admin',reports:'admin',signin:'invitation',reset:'signin',essentials:'signin',pending:'essentials'};
  parent.signup='signin';parent.emailverify='signup';
  let toastTimer, returnFocus;
  function announce(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
  function icons(){window.lucide.createIcons();}
  function change(screen, reset=true){if(!info[screen])return;s.screen=screen;if(reset)s.state='ready';$('#state').value=s.state;location.hash=screen;render();$('#app-content').scrollTop=0;$('#app-content').focus({preventScroll:true});}
  function header(){const id=s.screen;const title={home:'Greek Ties',events:'Events',chats:'Chats',network:'Network',me:'Me',event:'Event',conversation:'Chapter chat',mentorship:'Jordan Lee'}[id]||info[id][2];let actions='';if(id==='home')actions=ib('bell','go:notifications','Notifications');if(id==='events')actions=ib('plus','go:create','Create event','gold');if(id==='network')actions=ib('map','go:map','Alumni map');if(id==='chats')actions=ib('inbox','go:requests','Mentorship requests');if(id==='event')actions=ib('share-2','go:share','Share event');if(id==='conversation')actions=ib('info','go:threadinfo','Conversation details');if(id==='mentorship')actions=ib('refresh-cw','refresh-thread','Refresh conversation');if(id==='me')actions=ib('settings','go:settings','Settings');return `<header class="app-head">${parent[id]?ib('arrow-left',`go:${parent[id]}`,'Back'):''}<div class="heading"><h2>${title}</h2>${id==='conversation'?'<small>Sigma Phi Epsilon / chapter group</small>':id==='mentorship'?'<small>Accepted mentorship</small>':''}</div>${actions}</header>`}
  function tabs(){const id=s.screen;const active=rootRoutes.includes(id)?id:({calendar:'events',notifications:'home',opportunities:'network',map:'network'})[id];if(!active)return '';return `<div class="tabs">${[['home','house','Home'],['chats','messages-square','Chats'],['events','calendar-days','Events'],['network','users-round','Network'],['me','user-round','Me']].map(([r,i,t])=>`<button data-action="go:${r}" class="${active===r?'active':''}" ${active===r?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</div>`}
  function dock(){if(s.state!=='ready')return '';if(s.screen==='event')return `<div class="dock rsvp-dock"><span class="small">${s.rsvp==='going'?'You\'re going':s.rsvp==='maybe'?'You\'re interested':'You can\'t go'} / ${s.rsvp==='going'?38:37} going</span>${button(`Change RSVP ${icon('chevron-down')}`,'rsvp')}</div>`;if(['conversation','mentorship'].includes(s.screen))return `<form class="composer" id="message-form"><label class="sr-only" hidden for="message">Message</label><textarea id="message" name="message" rows="1" placeholder="Message ${s.screen==='mentorship'?'Jordan':'the chapter'}" aria-label="Message" required maxlength="2000"></textarea><button class="icon-btn" aria-label="Send message" title="Send message" type="submit">${icon('send')}</button></form>`;if(s.screen==='profile')return `<div class="dock">${go('Request mentorship','request','primary')}</div>`;return '';}
  function eventCard(){return `<button class="event-card" data-action="go:event">${photo()}<div class="event-copy">${tag('ALUMNI WEEKEND')}<h3>Back in Santa Barbara</h3><div class="event-meta">${icon('calendar-days')}Sat, Nov 7 / 4:00 PM PST</div><div class="event-meta">${icon('map-pin')}Campus lawn, Santa Barbara</div><div class="faces">${['Jordan Lee','Maya Patel','Sam Rivera','Taylor Chen'].map((n,i)=>avatar(n,i%2?'gold':'')).join('')}<span class="small">+34 / 38 going</span></div></div></button>`}
  function home(){return `<div class="chapter-band"><span class="eyebrow">YOUR CHAPTER, BEYOND COLLEGE</span><h2>Sigma Phi Epsilon</h2><p>University of California, Santa Barbara</p></div><div class="counts"><button data-action="members:Active"><b>84</b><span>Active members ${icon('arrow-up-right')}</span></button><button data-action="members:Alumni"><b>216</b><span>Alumni ${icon('arrow-up-right')}</span></button></div><section class="section">${sectionTitle('Get together',go('All events','events'))}${eventCard()}</section><section class="section">${sectionTitle('Pick up the conversation',go('Inbox','chats'))}${row('Chapter chat','Sam: See you on the lawn this Saturday.','conversation',avatar('Chapter chat','gold'),'<span class="chat-unread">3</span>')}${row('Jordan Lee','Happy to look over your portfolio.','mentorship')}</section><section class="section">${sectionTitle('Give the next chapter a hand')}${row('Find a mentor','Talk to someone who has been there.','network',icon('handshake'))}${row('Explore opportunities','Roles shared within your chapter.','opportunities',icon('briefcase-business'))}</section>`}
  function invitation(){return `<div class="pad"><div class="brand-lockup"><span class="brand-mark">GT</span>Greek Ties</div></div>${photo()}<div class="pad"><span class="eyebrow">SIGMA PHI EPSILON / UCSB</span><h1 class="display">Your chapter.<br>Still your people.</h1><p class="subtitle">Catch up, make plans, and help the next generation.</p><div class="gold-rule"></div><div class="stack">${go('Continue to Greek Ties','signin','primary')}${go('Already a member? Sign in','signin','secondary')}</div><p class="small muted top-space">Chapter membership is reviewed. Member details stay private.</p></div>`}
  function signin(){return `<div class="pad"><span class="tag">Sigma Phi Epsilon / UCSB</span><h1 class="display">Welcome back.</h1><p class="subtitle">Sign in to continue with your chapter invitation.</p><form id="signin-form">${field('Email','email','alex@example.test','email','required autocomplete="off"')}${field('Password','password','','password','required minlength="8" autocomplete="off" placeholder="Use any 8+ characters in this prototype"')}<div class="stack"><button class="primary" type="submit">Sign in</button>${go('Forgot password?','reset','text-button')}</div></form><div class="divider"></div>${button('Create an account','signup','secondary')}<p class="micro muted top-space">By continuing, you agree to the Terms and Privacy Policy.</p>${button('Terms & privacy','legal','text-button')}</div>`}
  function reset(){return `<div class="pad"><h1 class="display">A fresh start.</h1><p class="subtitle">Enter your email to request a password reset.</p><form id="reset-form">${field('Email','email','alex@example.test','email','required autocomplete="off"')}<button class="primary" type="submit">Send reset link</button><p id="reset-status" class="inline-status" role="status"></p></form></div>`}
  function essentials(){return `<div class="pad"><span class="eyebrow">YOUR CHAPTER</span><h1 class="display">A little about you.</h1><div class="notice">Sigma Phi Epsilon<br>University of California, Santa Barbara</div><form id="essentials-form">${field('Full name','name',s.pendingName,'text','required maxlength="100"')}${field('Graduation year','year','2026','number','required min="1940" max="2040"')}<fieldset style="border:0;padding:0;margin:0"><legend class="small">I am here to</legend><label class="checkrow"><input type="checkbox" name="find" checked><span>Find guidance</span></label><label class="checkrow"><input type="checkbox" name="offer"><span>Offer help</span></label></fieldset><p class="small muted">You can do both. Professional details and a photo can wait.</p><button class="primary" type="submit">Request to join</button></form></div>`}
  function pending(){return `<div class="pad"><span class="brand-mark">GT</span><h1 class="display">Your request is with your chapter.</h1><p class="subtitle">A chapter administrator will review your membership. You can check your status here.</p><ul class="steps"><li>${icon('circle-check')}Profile saved</li><li>${icon('clock-3')}Chapter approval pending</li></ul><div class="stack">${button('Check status','check-status')}${go('Edit your details','essentials','secondary')}</div><p class="small muted top-space">${esc(s.pendingName)} / Sigma Phi Epsilon</p></div>`}
  function events(calendar=false){
    const reunion=calendar?s.selectedDay===7:['All','Alumni'].includes(s.eventCategory);
    const meeting=calendar?s.selectedDay===12:['All','Chapter'].includes(s.eventCategory);
    const coffee=calendar?s.selectedDay===19:['All','Social'].includes(s.eventCategory);
    return `<div class="pad no-bottom"><div class="segments" role="tablist">${[['events','Agenda'],['calendar','Calendar']].map(([id,label])=>`<button role="tab" aria-selected="${s.screen===id}" data-action="go:${id}">${label}</button>`).join('')}</div>${calendar?`<div class="section-title top-space"><h3>November 2026</h3>${tag('PST')}</div><div class="calendar">${['S','M','T','W','T','F','S'].map(d=>`<span>${d}</span>`).join('')}${Array.from({length:30},(_,i)=>`<button aria-label="November ${i+1}, 2026" aria-pressed="${s.selectedDay===i+1}" data-action="day:${i+1}" class="${[7,12,19].includes(i+1)?'event-day':''} ${s.selectedDay===i+1?'selected':''}">${i+1}</button>`).join('')}</div>`:`<div class="chips">${['All','Alumni','Chapter','Social'].map(c=>`<button class="chip" data-action="eventcat:${c}" aria-pressed="${s.eventCategory===c}">${c}</button>`).join('')}</div>`}</div><section class="section">${sectionTitle(calendar?`November ${s.selectedDay}`:'Coming up')}${reunion?eventCard():''}${meeting?row('Chapter meeting','Thu, Nov 12 / 6:00 PM PST','event','<span class="date-block">NOV<b>12</b></span>'):''}${coffee?row('Coffee & connections','Thu, Nov 19 / 10:00 AM PST','event','<span class="date-block">NOV<b>19</b></span>'):''}${!reunion&&!meeting&&!coffee?'<p class="empty-inline">No chapter events on this day.</p>':''}</section><section class="section"><p class="small muted">All event times shown in America/Los_Angeles.</p></section>`;
  }
  function event(){const d=s.eventDraft;return `${photo()}<div class="section">${tag(d.category.toUpperCase())}<h1 class="display">${esc(d.title)}</h1><div class="fact"><span class="icon-btn">${icon('calendar-days')}</span><div><strong>${s.published?esc(d.date):'Saturday, November 7'}</strong><p>${s.published?esc(d.time):'4:00 PM'} - ${s.published?esc(d.end||''):'6:00 PM'} PST</p><p>America/Los_Angeles</p></div></div><div class="fact"><span class="icon-btn">${icon('map-pin')}</span><div><strong>${esc(d.location)}</strong><p>Shared with approved chapter members</p></div></div><div class="button-row">${button(`${icon('calendar-plus')} Add to calendar`,'calendar-export','secondary')}${go(`${icon('share-2')} Share`,'share','secondary')}</div></div><section class="section">${sectionTitle('Hosted by')}${row('Maya Patel',"Class of 2015 / alumni volunteer",'profile',avatar('Maya Patel','gold'))}</section><section class="section">${sectionTitle('Back together, in person.')}<p class="subtitle">${esc(d.description)}</p><p class="small muted">Come as you are. Students and alumni are welcome.</p></section><section class="section">${sectionTitle('Who is coming',go('View guests','guests'))}<p class="small muted">${s.rsvp==='going'?38:37} going / ${s.rsvp==='maybe'?8:7} interested</p><div class="faces">${members.slice(0,4).map(m=>avatar(m.name,m.cls)).join('')}<span class="small">+${s.rsvp==='going'?34:33} others</span></div></section><section class="section">${sectionTitle('Before you go')}<p class="small muted">Questions? Reach out to your host or an existing chapter conversation.</p>${go('Open chapter chat','conversation','secondary')}${go('Edit event','create','text-button')}</section>`}
  function guests(){return `<div class="pad"><p class="small muted">Back in Santa Barbara</p><div class="segments" role="tablist">${['Going','Interested'].map(t=>`<button role="tab" aria-selected="${(s.guestTab||'Going')===t}" data-action="guests:${t}">${t} / ${t==='Going'?(s.rsvp==='going'?38:37):(s.rsvp==='maybe'?8:7)}</button>`).join('')}</div><div class="top-space">${((s.guestTab||'Going')==='Going'?members.slice(0,4):members.slice(4)).map(m=>row(m.name,`Class of ${m.year} / ${m.kind}`,'profile',avatar(m.name,m.cls))).join('')}</div><p class="micro muted top-space">Only members whose profiles you can access are shown.</p>${button('Load more','more-guests','secondary')}</div>`}
  function create(){const d=s.eventDraft;return `<form id="event-form"><div class="preview-cover">${photo()}${ib('image-plus','cover','Choose event cover')}</div><div class="pad">${field('Event name','title',d.title,'text','required maxlength="100"')}<label class="form-field">Category<select name="category">${['Chapter','Alumni','Philanthropy','Social','Recruitment'].map(c=>`<option ${d.category===c?'selected':''}>${c}</option>`).join('')}</select></label><div class="form-grid">${field('Date','date',d.date,'date','required')}${field('Start time','time',d.time,'time','required')}</div><p class="micro muted">America/Los_Angeles. Timezone remains visible through review.</p>${field('Location','location',d.location,'text','required maxlength="180"')}${textArea('Description','description',d.description,'required maxlength="2000"')}<details ${s.optional?'open':''}><summary class="text-button">Optional details</summary>${field('End time','end',d.end,'time')}<p class="small muted">Visibility: approved chapter members. Public publishing is not available.</p></details><div class="notice top-space">Only approved chapter members can open this event.</div><button class="primary" type="submit">Review event ${icon('arrow-right')}</button><p id="form-error" class="error-text" role="alert"></p></div></form>`}
  function review(){const d=s.eventDraft;return `${photo()}<div class="pad">${tag('READY TO REVIEW')}<h1 class="display">${esc(d.title)}</h1><dl class="summary-list"><dt>When</dt><dd>${esc(d.date)} / ${esc(d.time)}${d.end?` - ${esc(d.end)}`:''}<br>America/Los_Angeles</dd><dt>Where</dt><dd>${esc(d.location)}</dd><dt>Audience</dt><dd>Approved chapter members</dd><dt>Category</dt><dd>${esc(d.category)}</dd></dl><div class="divider"></div><p class="subtitle">${esc(d.description)}</p><div class="stack">${button('Publish event','publish')}${go('Keep editing','create','secondary')}</div><p class="micro muted top-space">Publishing does not automatically invite or message anyone.</p></div>`}
  function share(){return `<div class="pad"><span class="tag">MEMBERS ONLY</span><h1 class="display">Bring your people together.</h1><p class="subtitle">Back in Santa Barbara / Nov 7</p><div class="notice">A shared link does not grant chapter membership. Guests must sign in and have access to the event.</div>${button(`${icon('link')} Copy protected event link`,'copy-event','secondary')}<div class="divider"></div>${sectionTitle('Share to a conversation')}${threads.filter(t=>t[4]==='Groups').slice(0,3).map(t=>`<button class="row" data-action="share-to:${t[0]}">${avatar(t[0],t[6])}<span class="grow"><strong>${t[0]}</strong><span class="small muted">Review before sending</span></span>${icon('chevron-right')}</button>`).join('')}<p class="micro muted top-space">Guest identities and private location details stay out of external previews.</p></div>`}
  function chats(){return `<div class="pad no-bottom"><label class="search">${icon('search')}<input id="chat-search" placeholder="Search conversations" aria-label="Search conversations" value="${esc(s.chatQuery||'')}"></label><div class="segments" role="tablist">${['All','Groups','Mentorship'].map(c=>`<button role="tab" aria-selected="${s.chatTab===c}" data-action="chattab:${c}">${c}</button>`).join('')}</div></div><div class="pad" id="thread-results">${threadRows()}</div>`}
  function threadRows(){const list=threads.filter(t=>(s.chatTab==='All'||s.chatTab===t[4])&&`${t[0]} ${t[1]}`.toLowerCase().includes((s.chatQuery||'').toLowerCase()));return list.map(t=>`<button class="row" data-action="go:${t[5]}">${avatar(t[0],t[6])}<span class="grow"><strong>${t[0]}</strong><span class="small muted">${t[1]}</span>${t[4]==='Mentorship'?'<span class="micro muted">Accepted mentorship</span>':''}</span><span class="chat-side"><time>${t[2]}</time>${t[3]?`<span class="chat-unread">${t[3]}</span>`:''}</span></button>`).join('')||'<p class="empty-inline">No matching conversations.</p>';}
  function msg(name,text,time,own=false,reaction=false){return `<div class="message ${own?'own':''}">${own?'':avatar(name,'gold')}<div class="message-body">${own?'':`<b>${name}</b>`}<div class="bubble">${esc(text)}</div>${reaction?`<button class="reaction" aria-label="Like message, ${s.reaction?3:2} likes" aria-pressed="${s.reaction}" data-action="react">${icon('heart')} ${s.reaction?3:2}</button>`:''}<time>${time}${own?' / Sent':''}</time></div></div>`}
  function conversation(mentorship=false){return `<div class="conversation"><div class="day-rule">Today / October 15</div>${mentorship?`${msg('Jordan Lee','Good to meet you, Alex. What kind of design work are you exploring?','9:32 AM')}${msg('Alex Morgan','I am putting together my first product design portfolio.','9:34 AM',true)}${msg('Alex Morgan','Would love your advice on choosing the right projects.','9:35 AM',true)}${msg('Jordan Lee','Happy to look over your portfolio. Start with a problem you know well.','9:36 AM')}`:`${msg('Maya Patel','Alumni weekend is coming together. Looking forward to seeing everyone.','9:32 AM',false,true)}${msg('Sam Rivera','See you on the lawn this Saturday.','9:34 AM')}${msg('Alex Morgan','I will be there! Bringing a few photos from last year.','9:36 AM',true)}${msg('Maya Patel','Perfect. There will be plenty of time to catch up.','9:38 AM')}`}${s.messages.filter(m=>m.thread===s.screen).map(m=>msg('Alex Morgan',m.text,'9:41 AM',true)).join('')}<div id="message-end"></div></div>`}
  function threadinfo(){return `<div class="profile-header">${avatar('Chapter chat','big gold')}<h2>Chapter chat</h2><p class="small">Sigma Phi Epsilon / UCSB</p>${tag('CHAPTER MEMBERS')}</div><div class="section">${sectionTitle('About this conversation')}<p class="subtitle">Everyday plans, chapter updates and keeping in touch across generations.</p>${row('Chapter directory','Browse approved members','network',icon('users-round'))}${row('Refresh conversation','Check for missed updates','conversation',icon('refresh-cw'))}${button('Report a concern','report','secondary')}</div>`}
  function requests(){return `<div class="pad"><p class="subtitle">A little context before a conversation.</p><div class="notice">Accepting opens a private mentorship conversation. Declining keeps it closed.</div>${row('Sam Rivera','Class of 2027 / career guidance','profile',avatar('Sam Rivera','sage'))}<p class="subtitle top-space">I would love to hear how you chose your first internship.</p><div class="button-row">${button('Accept','accept-request')}${button('Decline','decline-request','secondary')}</div><div id="request-decision" class="inline-status" role="status"></div></div>`}
  function network(){return `<div class="pad no-bottom"><p class="small muted">300 chapter members / 84 active / 216 alumni</p><div class="button-row"><label class="search" style="flex:1">${icon('search')}<input id="people-search" aria-label="Search members" placeholder="Name, company or city" value="${esc(s.peopleQuery)}"></label>${ib('sliders-horizontal','go:filters','Filter members','gold')}</div><div class="segments" role="tablist">${['All','Active','Alumni'].map(c=>`<button role="tab" aria-selected="${s.member===c}" data-action="member:${c}">${c}</button>`).join('')}</div><div class="chips"><button class="chip" data-action="mentor-filter" aria-pressed="${s.mentor}">Open to mentor</button>${go('Opportunities','opportunities','chip')}${go('Map','map','chip')}</div></div><div class="pad" id="member-results">${memberRows()}</div>`}
  function matchingMembers(){return members.filter(m=>(s.member==='All'||m.kind===s.member)&&(s.industry==='All'||m.industry===s.industry)&&(!s.city||m.city.toLowerCase().includes(s.city.toLowerCase()))&&(!s.mentor||m.mentor)&&`${m.name} ${m.company} ${m.city}`.toLowerCase().includes(s.peopleQuery.toLowerCase()));}
  function memberRows(){const list=matchingMembers();return `<p class="micro muted">${list.length} matching results in this preview</p>${list.map(m=>`<button class="row" data-action="profile:${m.name}">${avatar(m.name,m.cls)}<span class="grow"><strong>${m.name} <span class="muted">'${m.year.slice(-2)}</span></strong><span class="small muted">${m.job} / ${m.company}</span><span class="micro muted">${m.city}</span>${m.mentor?`<span style="display:block;margin-top:6px">${tag('Open to mentor')}</span>`:''}</span>${icon('chevron-right')}</button>`).join('')||`<p class="empty-inline">No members match these filters.</p>${button('Clear filters','clear-filters','secondary')}`}`}
  function filters(){return `<form id="filter-form" class="pad"><label class="form-field">Membership<select name="member">${['All','Active','Alumni'].map(v=>`<option ${s.member===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="form-field">Industry<select name="industry">${['All','Technology','Consulting','Finance'].map(v=>`<option ${s.industry===v?'selected':''}>${v}</option>`).join('')}</select></label>${field('City','city',s.city,'text','placeholder="Any city"')}<label class="checkrow"><input type="checkbox" name="mentor" ${s.mentor?'checked':''}><span>Open to mentor</span></label><div class="stack"><button class="primary" type="submit">Show matching members</button>${button('Clear filters','clear-filters','secondary')}</div></form>`}
  function profile(){const m=members.find(m=>m.name===s.profileName)||members[0];return `<div class="profile-header">${avatar(m.name,`big ${m.cls}`)}<h2>${m.name}</h2><p class="small">${m.job} / ${m.company}</p><p class="small muted">Class of ${m.year} / ${m.city}</p>${m.mentor?tag('Open to mentor'):tag(m.kind)}</div><section class="section">${sectionTitle('About')}<p class="subtitle">I care about making the next step a little easier for people from our chapter. Always glad to share what I have learned.</p></section><section class="section">${sectionTitle('Professional details')}<div class="fact">${icon('briefcase-business')}<div><strong>${m.company}</strong><p>${m.industry}</p></div></div><div class="fact">${icon('graduation-cap')}<div><strong>Sigma Phi Epsilon</strong><p>UC Santa Barbara / ${m.year}</p></div></div>${button('View professional link','professional-link','secondary')}</section><section class="section">${button('Report or block','report','text-button')}</section>`}
  function request(){return `<div class="pad">${s.requestSent?`<span class="tag green">REQUEST SENT</span><h1 class="display">The next step is theirs.</h1><p class="subtitle">Your request is pending. A conversation opens only after it is accepted.</p>${go('Back to the network','network','primary')}`:`<h1 class="display">Start with a question.</h1><p class="subtitle">To ${esc(s.profileName||'Jordan Lee')}</p><form id="mentorship-form"><label class="form-field">Topic<select name="topic"><option>Career guidance</option><option>Portfolio feedback</option><option>Industry introduction</option></select></label>${textArea('Your message','note','I am exploring product design roles and would value your advice on where to start.','required minlength="10" maxlength="1000"')}<p class="micro muted">Keep it personal. Contact details are not shared automatically.</p><button class="primary" type="submit">Send mentorship request</button></form>`}</div>`}
  function opportunities(){return `<div class="pad"><p class="subtitle">Shared by people from your chapter.</p>${row('Associate product designer','Northstar / San Francisco / Design','job',icon('briefcase-business'))}${row('Summer analyst internship','Harbor / New York / Finance','job',icon('briefcase-business'))}${row('Strategy associate','Westbridge / Los Angeles / Consulting','job',icon('briefcase-business'))}${button(`${icon('plus')} Share an opportunity`,'new-job','secondary')}</div>`}
  function job(){return `<div class="pad">${tag('OPPORTUNITY')}<h1 class="display">Associate product designer</h1><p class="subtitle">Northstar / San Francisco</p>${row('Jordan Lee','Shared with your chapter','profile')}<div class="divider"></div>${sectionTitle('About the role')}<p class="subtitle">Work with a small product team to turn customer research into useful, thoughtful experiences.</p><ul class="subtitle"><li>Collaborate with research and engineering.</li><li>Present work clearly and welcome feedback.</li><li>Bring a portfolio that shows your process.</li></ul><div class="notice">Applications open on the employer's website. Greek Ties does not submit an application for you.</div>${button('View application destination','apply-job')}${go('Ask about mentorship','request','text-button')}</div>`}
  function map(){return `<div class="map-canvas" role="img" aria-label="Schematic California city map with fictional alumni clusters, not geographic map data"><div class="land"></div><div class="road"></div><div class="road two"></div><div class="road three"></div><span class="map-disclaimer">City-level preview</span><button class="pin ${s.mapCity==='San Francisco'?'selected':''}" style="top:49px;left:38%" data-action="city:San Francisco">SF / 12</button><button class="pin ${s.mapCity==='Santa Barbara'?'selected':''}" style="top:145px;left:33%" data-action="city:Santa Barbara">SB / 8</button><button class="pin ${s.mapCity==='Los Angeles'?'selected':''}" style="top:207px;left:57%" data-action="city:Los Angeles">LA / 16</button><span class="map-label">Pacific Ocean</span></div><div class="pad"><div class="notice">Your city is ${s.sharing?'shared with approved chapter members':'not shared'}. ${go('Manage visibility','privacy')}</div>${sectionTitle(s.mapCity)}<p class="small muted">Alumni who chose to share their city.</p>${row(s.mapCity==='Los Angeles'?'Maya Patel':'Jordan Lee','Open to mentor','profile',avatar(s.mapCity==='Los Angeles'?'Maya Patel':'Jordan Lee','gold'))}${go('Browse the directory instead','network','secondary')}</div>`}
  function me(){return `<div class="profile-header">${avatar('Alex Morgan','big gold')}<h2>Alex Morgan</h2><p class="small">Class of 2026 / Sigma Phi Epsilon</p><p class="small muted">UC Santa Barbara</p><div class="top-space">${go('Edit profile','editprofile','secondary')}</div></div><div class="section">${row('My chapter','Sigma Phi Epsilon / UCSB','network',icon('users-round'))}${row('Mentorship requests','Review invitations to connect','requests',icon('handshake'))}${row('Map visibility',s.sharing?'City shared with chapter':'Off / your city is private','privacy',icon('map-pin'))}${row('Notifications','Messages, requests and chapter updates','notifications',icon('bell'))}${row('Settings & safety','Account and privacy controls','settings',icon('shield-check'))}</div><div class="section">${sectionTitle('Chapter tools')}${row('Chapter management','Available to authorized administrators','admin',icon('settings-2'))}</div>`}
  function editprofile(){return `<form class="pad" id="profile-form"><div class="section-title">${avatar('Alex Morgan','big gold')}${button('Change photo','avatar','text-button')}</div>${field('Name','name','Alex Morgan','text','required')}${field('Graduation year','year','2026','number','required min="1940" max="2040"')}${field('Job title','title','Product designer')}${field('Company','company','Northstar')}${field('City','city','San Francisco')}${field('LinkedIn profile','linkedin','','url','placeholder="https://www.linkedin.com/in/..."')}${textArea('About','bio','Happy to connect with people from my chapter.')}<label class="checkrow"><input type="checkbox" checked><span>Open to mentoring</span></label><p class="small muted">Editing your city does not turn on map sharing.</p><button class="primary" type="submit">Save profile</button></form>`}
  function privacy(){return `<div class="pad">${tag(s.sharing?'CITY SHARED':'OFF BY DEFAULT')}<h1 class="display">Be discoverable.<br>On your terms.</h1><p class="subtitle">Show your chosen city to approved members of your chapter on the alumni map.</p><div class="notice">This is not live location. Greek Ties does not need your device's precise location for city sharing.</div><div class="fact">${icon('map-pin')}<div><strong>San Francisco</strong><p>Your profile city, not a home address</p></div></div><div class="fact">${icon('users-round')}<div><strong>Approved chapter members</strong><p>No public map or external link previews</p></div></div>${s.sharing?button('Stop sharing my city','stop-sharing','secondary'):`<label class="checkrow"><input id="map-consent" type="checkbox" ${s.consent?'checked':''}><span>I agree to show my city on my chapter's alumni map. I can stop sharing at any time.</span></label>${button('Share my city','share-city','primary',s.consent?'':'disabled')}`}<p class="micro muted top-space">Available only for approved alumni. An empty or old consent value remains off.</p></div>`}
  function settings(){return `<div class="pad">${sectionTitle('Privacy & safety')}${row('Map visibility',s.sharing?'City shared':'Off','privacy',icon('map-pin'))}${row('Blocked members','Manage your boundaries','blocked',icon('user-round-x'))}${button('Terms & privacy','legal','text-button')}<div class="divider"></div>${sectionTitle('Account')}${row('Reset password','Request a secure reset link','reset',icon('key-round'))}<div class="notice">Account deletion is unavailable in this private QA build. No deletion request will be submitted.</div>${button('Delete account','deletion','secondary','disabled')}${button('Sign out','signout','secondary')}<p class="micro muted top-space">Greek Ties / private QA design preview</p></div>`}
  function blocked(){return `<div class="pad"><p class="subtitle">Blocked members cannot contact you through supported chapter messaging.</p>${s.blocked?`<div class="row">${avatar('Casey Brooks','rose')}<span class="grow"><strong>Casey Brooks</strong><span class="small muted">Blocked</span></span>${button('Unblock','unblock','text-button')}</div>`:'<p class="empty-inline">No blocked members.</p>'}</div>`}
  function notifications(){return `<div class="pad">${sectionTitle('Today')}${row('Jordan replied','Mentorship / 1 hour ago','mentorship',icon('messages-square'))}${row('A mentorship request','Sam Rivera / 2 hours ago','requests',icon('handshake'))}${sectionTitle('Earlier')}${row('Back in Santa Barbara','Your chapter event / Nov 7','event',icon('calendar-days'))}</div>`}
  function admin(){return `<div class="pad"><span class="tag">CHAPTER ADMINISTRATOR</span><h1 class="display">Take care of your chapter.</h1>${row('Membership approvals','1 request to review','approvals',icon('user-round-check'))}${row('Invite members','Chapter-bound invitations','invite',icon('mail-plus'))}${row('Reports','1 report to review','reports',icon('flag'))}${row('Chapter conversations','Review channel details','threadinfo',icon('messages-square'))}<p class="micro muted top-space">These tools are restricted to authorized chapter administrators.</p></div>`}
  function approvals(){return `<div class="pad">${s.approved?'<p class="empty-inline">No pending membership requests.</p>':`${row('Alex Morgan','Requested Oct 15 / graduation year 2026','profile',avatar('Alex Morgan','gold'))}<dl class="summary-list top-space"><dt>Chapter</dt><dd>Sigma Phi Epsilon / UCSB</dd><dt>Status</dt><dd>Pending review</dd></dl><div class="notice">Confirm chapter affiliation before approving. Graduation year alone does not establish membership.</div><div class="button-row">${button('Approve','approve-member')}${button('Decline','decline-member','secondary')}</div>`}</div>`}
  function invite(){return `<div class="pad"><span class="eyebrow">SIGMA PHI EPSILON / UCSB</span><h1 class="display">More of your people.</h1><p class="subtitle">Invite members into the same chapter. An invitation starts a membership review, not automatic access.</p><div class="notice">This prototype does not generate a real invitation link.</div><dl class="summary-list"><dt>Audience</dt><dd>Intended chapter members</dd><dt>Access</dt><dd>Subject to chapter approval</dd><dt>Expiration</dt><dd>7 days after creation</dd></dl><div class="stack top-space">${button('Create chapter invitation','create-invite')}${button('Review existing invitation','review-invite','secondary')}</div></div>`}
  function reports(){return `<div class="pad">${tag('PRIVATE TO REVIEWERS')}<h1 class="display">Review with care.</h1><div class="row">${icon('flag')}<span class="grow"><strong>Message reported</strong><span class="small muted">Chapter chat / Oct 15</span></span>${tag('Open')}</div><p class="subtitle top-space">A member reported an unwanted personal remark.</p><div class="stack">${button('Review report','report-detail')}${button('Mark reviewed','mark-reviewed','secondary')}</div><p class="micro muted top-space">A review does not automatically remove content or change membership.</p></div>`}
  function signup(){return `<div class="pad"><span class="tag">SIGMA PHI EPSILON / UCSB</span><h1 class="display">Make yourself<br>at home.</h1><p class="subtitle">Create your account, then request chapter membership.</p><form id="signup-form">${field('Email','email','alex@example.test','email','required autocomplete="off"')}${field('Password','password','','password','required minlength="8" autocomplete="off"')}<p class="small muted">Use at least 8 characters in this preview. The app must use its actual authentication password policy.</p><label class="checkrow"><input type="checkbox" required><span>I agree to the Terms and Privacy Policy.</span></label>${button('Read terms & privacy','legal','text-button')}<button class="primary" type="submit">Create account</button></form><div class="top-space">${go('Already have an account? Sign in','signin','text-button')}</div></div>`}
  function emailverify(){return `<div class="pad"><span class="brand-mark">GT</span><h1 class="display">Check your email.</h1><p class="subtitle">Follow the verification link to continue. Chapter membership still needs approval.</p><div class="notice">No email is sent by this design preview.</div><div class="stack">${button('Resend verification email','resend-email','secondary')}${go('Change email','signup','text-button')}</div><p class="small muted top-space">Once your email is verified, you can finish your profile.</p>${go('Preview the next step','essentials','primary')}</div>`}
  const views={invitation,signin,signup,emailverify,reset,essentials,pending,home,notifications,events:()=>events(false),calendar:()=>events(true),event,guests,create,review,share,chats,conversation:()=>conversation(false),threadinfo,mentorship:()=>conversation(true),requests,network,filters,profile,request,opportunities,job,map,me,editprofile,privacy,settings,blocked,admin,approvals,invite,reports};
  function stateView(){const subject=info[s.screen][2].toLowerCase();if(s.state==='loading')return `<div class="pad" role="status" aria-label="Loading ${subject}"><div class="skeleton"></div><div class="skeleton big"></div><div class="skeleton"></div><div class="skeleton"></div><p class="small muted">Loading ${subject}...</p></div>`;const content={empty:['inbox','Nothing here yet.',`There is no ${subject} content to show right now.`],error:['cloud-off','Could not load this.',`Your saved information has not been changed. Try loading ${subject} again.`],offline:['wifi-off','You are offline.','Reconnect before making changes. No action has been submitted.'],denied:['lock-keyhole','This is no longer available.','Your access may have changed. Private content has been cleared from this view.']}[s.state];return `<div class="state-panel">${icon(content[0])}<h3>${content[1]}</h3><p>${content[2]}</p>${s.state==='denied'?go('Back to Home','home','primary'):button(s.state==='empty'?'Refresh':'Retry','retry')}</div>`;}
  function render(){const data=info[s.screen];$('#screen-name').textContent=data[2];$('#screen-note').textContent=data[5];$('#intent-title').textContent=data[3];$('#intent').textContent=data[4];$('#capability-note').textContent=data[5];$('#app-header').innerHTML=header();$('#app-content').innerHTML=s.state==='ready'?views[s.screen]():stateView();$('#app-dock').innerHTML=dock();$('#app-tabs').innerHTML=tabs();$('#overlay').innerHTML='';document.querySelectorAll('#screen-nav button').forEach(b=>b.setAttribute('aria-current',b.dataset.screen===s.screen?'page':'false'));icons();if(['conversation','mentorship'].includes(s.screen)&&s.state==='ready')requestAnimationFrame(()=>{$('#app-content').scrollTop=$('#app-content').scrollHeight});}
  function closeSheet(){const focus=returnFocus;$('#overlay').innerHTML='';if(focus?.isConnected)focus.focus();}
  function sheet(title,body){returnFocus=document.activeElement;$('#overlay').innerHTML=`<div class="sheet-shade"><section class="sheet" role="dialog" aria-modal="true" aria-label="${title}"><div class="sheet-head"><h2>${title}</h2>${ib('x','close','Close dialog')}</div>${body}</section></div>`;icons();requestAnimationFrame(()=>$('#overlay button')?.focus());}
  function confirm(title,body,action,label='Confirm'){sheet(title,`<p class="top-space">${body}</p>${button(label,action)}${button('Cancel','close','text-button')}`);}
  function saveDraft(form){const d=new FormData(form);s.eventDraft={title:d.get('title').trim(),category:d.get('category'),date:d.get('date'),time:d.get('time'),location:d.get('location').trim(),description:d.get('description').trim(),end:d.get('end')};}
  document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(a.startsWith('go:')){change(a.slice(3));return;}if(a.startsWith('members:')){s.member=a.slice(8);change('network');return;}if(a.startsWith('member:')){s.member=a.slice(7);render();return;}if(a.startsWith('profile:')){s.profileName=a.slice(8);change('profile');return;}if(a.startsWith('chattab:')){s.chatTab=a.slice(8);render();return;}if(a.startsWith('eventcat:')){s.eventCategory=a.slice(9);render();return;}if(a.startsWith('guests:')){s.guestTab=a.slice(7);render();return;}if(a.startsWith('day:')){s.selectedDay=Number(a.slice(4));render();return;}if(a.startsWith('city:')){s.mapCity=a.slice(5);render();return;}if(a.startsWith('rsvp-choice:')){s.draftRsvp=a.slice(12);rsvpSheet();return;}if(a.startsWith('share-to:')){confirm('Share event?',`Send a protected link to ${esc(a.slice(9))}? No message is sent in this preview.`,'shared','Share event');return;}
    switch(a){
      case 'rsvp':s.draftRsvp=s.rsvp;rsvpSheet();break;
      case 'save-rsvp':s.rsvp=s.draftRsvp;render();announce('RSVP updated in this preview.');break;
      case 'close':closeSheet();break;
      case 'retry':s.state='ready';$('#state').value='ready';render();announce('Preview data restored.');break;
      case 'check-status':announce('Your chapter approval is still pending.');break;
      case 'signup':change('signup');break;
      case 'resend-email':announce('Resend simulated. No email was sent.');break;
      case 'legal':sheet('Terms & privacy',`<p class="top-space">Production must open the existing approved legal documents. This proposal does not replace them.</p>${button('Done','close')}`);break;
      case 'calendar-export':sheet('Add to your calendar',`<p class="top-space">Back in Santa Barbara<br>November 7, 2026 / 4:00-6:00 PM PST</p><p>Your calendar provider may receive the event title and location. This preview does not export or request permissions.</p>${button('Done','close')}`);break;
      case 'more-guests':announce('Only the sample guest rows are available in this design preview.');break;
      case 'cover':sheet('Event cover',`<p class="top-space">Use a chapter-owned photograph. Cover upload needs its own storage and privacy implementation.</p>${photo()}${button('Use this preview image','close')}`);break;
      case 'publish':s.published=true;change('event');announce('Preview published locally. No event was created.');break;
      case 'copy-event':sheet('Protected event link',`<p class="top-space">Example only: greekties.example/events/reunion</p><p>Never include private event details in an unauthenticated link preview. No link was copied.</p>${button('Done','close')}`);break;
      case 'shared':closeSheet();announce('Sharing simulated. No real message was sent.');break;
      case 'react':s.reaction=!s.reaction;{const top=$('#app-content').scrollTop;render();requestAnimationFrame(()=>$('#app-content').scrollTop=top)}break;
      case 'refresh-thread':announce('Conversation refreshed from preview data.');break;
      case 'accept-request':confirm('Accept mentorship?', 'A private conversation opens after acceptance.','accepted','Accept request');break;
      case 'accepted':change('mentorship');announce('Request accepted in this preview.');break;
      case 'decline-request':confirm('Decline request?', 'No conversation will be opened.','declined','Decline request');break;
      case 'declined':closeSheet();$('#request-decision').textContent='Request declined in this preview.';break;
      case 'mentor-filter':s.mentor=!s.mentor;render();break;
      case 'clear-filters':s.member='All';s.industry='All';s.city='';s.mentor=false;s.peopleQuery='';change('network');break;
      case 'professional-link':sheet('Open professional profile',`<p class="top-space">Open only the member-supplied, validated HTTPS link. No LinkedIn account connection or scraping is part of this release.</p>${button('Done','close')}`);break;
      case 'new-job':sheet('Share an opportunity',`<p class="top-space">Use the existing job creation service. This form is a layout reference only.</p>${field('Role','role','','text','placeholder="Role title"')}${field('Company','company')}${field('Application URL','url','','url')}${button('Save preview','new-job-done')}`);break;
      case 'new-job-done':closeSheet();announce('Opportunity preview saved. No job was posted.');break;
      case 'apply-job':sheet('Leave Greek Ties?',`<p class="top-space">Application destination: careers.example.test</p><p>External applications must use a validated, visible HTTPS destination. This sample does not open a website.</p>${button('Done','close')}`);break;
      case 'avatar':sheet('Profile photo',`<p class="top-space">Choose or remove a photo through the existing guarded avatar flow. No upload is performed here.</p>${button('Keep current photo','close')}`);break;
      case 'share-city':if(s.consent){s.sharing=true;render();announce('City sharing enabled in this preview only.')}break;
      case 'stop-sharing':s.sharing=false;s.consent=false;render();announce('Your city is private in this preview.');break;
      case 'signout':confirm('Sign out?', 'Return to the sign-in screen. Production must clear private cached content.','signedout','Sign out');break;
      case 'signedout':change('signin');break;
      case 'unblock':confirm('Unblock Casey?', 'This restores supported contact permissions.','unblocked','Unblock');break;
      case 'unblocked':s.blocked=false;render();break;
      case 'approve-member':confirm('Approve Alex?', 'Confirm affiliation before granting chapter access.','member-reviewed','Approve membership');break;
      case 'decline-member':confirm('Decline membership?', 'No chapter content will be made available.','member-reviewed','Decline membership');break;
      case 'member-reviewed':s.approved=true;render();announce('Decision recorded in this preview only.');break;
      case 'create-invite':sheet('Invitation preview',`<p class="top-space">Sigma Phi Epsilon / UCSB</p><div class="notice">Example only: greekties.example/join/preview</div><p>Expires 7 days after creation. The actual server is authoritative. No invitation has been created.</p>${button('Done','close')}`);break;
      case 'review-invite':sheet('Existing invitation',`<p class="top-space">Preview invitation / expires October 22, 2026</p>${button('Revoke invitation','revoke','secondary')}`);break;
      case 'revoke':confirm('Revoke invitation?', 'Future attempts to join with this link will fail. Existing memberships are unchanged.','revoked','Revoke');break;
      case 'revoked':closeSheet();announce('Revocation simulated.');break;
      case 'report':sheet('Report or block',`<p class="top-space">Choose a concern. A report is private to authorized reviewers.</p><label class="form-field">Reason<select><option>Unwanted contact</option><option>Harassment</option><option>Other</option></select></label>${textArea('Additional context','context')}${button('Submit report','report-sent')}${button('Block member','block-confirm','secondary')}`);break;
      case 'block-confirm':confirm('Block this member?', 'Supported messages and discovery access will be restricted.','block-done','Block member');break;
      case 'block-done':closeSheet();announce('Blocking simulated. No real member changed.');break;
      case 'report-sent':closeSheet();announce('Report simulated. No report was submitted.');break;
      case 'report-detail':sheet('Report details',`<p class="top-space">Synthetic report: unwanted personal remark in Chapter chat.</p><p>Inspect authorized context before any moderation action. No real reported content is included.</p>${button('Done','close')}`);break;
      case 'mark-reviewed':confirm('Mark reviewed?', 'This does not remove content or restrict membership.','report-reviewed','Mark reviewed');break;
      case 'report-reviewed':closeSheet();announce('Review simulated.');break;
    }
  });
  function rsvpSheet(){sheet('Your RSVP',`<p class="top-space">Back in Santa Barbara</p>${[['going','Going','I will be there'],['maybe','Interested','I am still deciding'],['declined',"Can't go",'Not this time']].map(([v,t,sub])=>`<button class="choice ${s.draftRsvp===v?'selected':''}" role="radio" aria-checked="${s.draftRsvp===v}" data-action="rsvp-choice:${v}">${icon(s.draftRsvp===v?'circle-check':'circle')}<span>${t}<small>${sub}</small></span></button>`).join('')}${button('Save response','save-rsvp')}`);}
  document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;const data=new FormData(f);if(f.id==='signin-form')change('essentials');if(f.id==='reset-form'){$('#reset-status').textContent='If this email has an account, a reset link will be sent. No email is sent in this preview.';}if(f.id==='essentials-form'){s.pendingName=data.get('name');change('pending');}if(f.id==='filter-form'){s.member=data.get('member');s.industry=data.get('industry');s.city=data.get('city');s.mentor=data.has('mentor');change('network');}if(f.id==='event-form'){if(data.get('end')&&data.get('end')<=data.get('time')){$('#form-error').textContent='End time must be after the start time on this date.';return;}saveDraft(f);change('review');}if(f.id==='mentorship-form'){s.requestSent=true;render();}if(f.id==='profile-form'){change('me');announce('Profile changes simulated. No member data was saved.');}if(f.id==='message-form'){const value=data.get('message').trim();if(!value)return;s.messages.push({thread:s.screen,text:value});render();$('#message')?.focus();}});
  document.addEventListener('submit',e=>{if(e.target.id==='signup-form'){e.preventDefault();change('emailverify');}});
  document.addEventListener('input',e=>{if(e.target.id==='people-search'){s.peopleQuery=e.target.value;$('#member-results').innerHTML=memberRows();icons();}if(e.target.id==='chat-search'){s.chatQuery=e.target.value;$('#thread-results').innerHTML=threadRows();icons();}});
  document.addEventListener('change',e=>{if(e.target.id==='map-consent'){s.consent=e.target.checked;const b=$('[data-action="share-city"]');if(b)b.disabled=!s.consent;}});
  document.addEventListener('keydown',e=>{const dialog=$('#overlay [role="dialog"]');if(!dialog)return;if(e.key==='Escape'){closeSheet();return;}if(e.key==='Tab'){const focusable=[...dialog.querySelectorAll('button:not([disabled]),input,select,textarea,a[href]')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
  let group='';$('#screen-nav').innerHTML=screens.map(x=>{const heading=x[0]!==group?`<p class="nav-group">${x[0]}</p>`:'';group=x[0];return `${heading}<button data-screen="${x[1]}">${x[2]}</button>`;}).join('');
  $('#screen-nav').addEventListener('click',e=>{const b=e.target.closest('[data-screen]');if(b)change(b.dataset.screen);});
  $('#state').addEventListener('change',e=>{s.state=e.target.value;render();});
  $('#viewport').addEventListener('change',e=>{$('#phone').style.width=`${e.target.value}px`;});
  $('#large').addEventListener('change',e=>$('#phone').classList.toggle('large',e.target.checked));
  $('#media').addEventListener('change',e=>$('#phone').classList.toggle('no-media',e.target.value==='none'));
  $('#status-icons').innerHTML=icon('signal')+icon('wifi')+icon('battery-full');
  window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(info[id]&&id!==s.screen)change(id);});
  s.screen=info[location.hash.slice(1)]?location.hash.slice(1):'home';render();
  window.GreekTiesDesign={screens:screens.map(x=>({id:x[1],name:x[2]})),go:change,getState:()=>({...s}),setState:v=>{s.state=v;$('#state').value=v;render();}};
})();
